<?php require __DIR__.'/config.php'; session_start(); if(isset($_POST['logout'])){session_destroy();header('Location: admin.php');exit;} if(!isset($_SESSION['admin'])){if($_SERVER['REQUEST_METHOD']==='POST'&&hash_equals(ADMIN_PASSWORD,(string)($_POST['password']??'')))$_SESSION['admin']=true;else{?><!doctype html><meta name="viewport" content="width=device-width"><title>Aladin Admin Login</title><style>body{font:16px system-ui;background:#eef2f9;display:grid;place-items:center;height:100vh}.box{background:white;padding:30px;border-radius:20px;width:min(320px,85vw)}input,button{padding:12px;width:100%;margin-top:10px;border-radius:9px;border:1px solid #ddd}button{background:#183b82;color:white}</style><form class="box" method="post"><h2>Aladin Admin</h2><p>Secure sign in</p><input type="password" name="password" placeholder="Admin password" required><button>Login</button></form><?php exit;}} $products=products_data(true); $arr=$products['data']??$products['products']??$products['items']??$products; if(isset($arr['products']))$arr=$arr['products']; ?>
<!doctype html><html lang="bn"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Aladin Admin</title><link rel="stylesheet" href="style.css"><body><header><a class="logo" href="/">Aladin Admin</a><form method="post"><button name="logout">Logout</button></form></header><main class="wrap"><h1>Store Overview</h1><div class="sectionHead"><h2>API Product Catalog</h2><span><?=is_array($arr)?count($arr):0?> products</span></div><p>এই প্যানেল API থেকে পণ্য দেখায়। API-তে অনুমোদিত admin endpoints না থাকায় এখানে supplier product/order পরিবর্তনের fake controls রাখা হয়নি।</p><div class="grid"><?php foreach(array_slice(is_array($arr)?$arr:[],0,50) as $p):?><article class="product pinfo"><h3><?=esc($p['name']??$p['title']??'Product')?></h3><strong>৳<?=number_format((float)($p['reseller_price']??$p['price']??0))?></strong><small>ID: <?=esc($p['_id']??$p['id']??'—')?></small></article><?php endforeach;?></div><h2>System</h2><p>API: <?=esc(API_BASE)?></p><p>Product cache TTL: 300 seconds (5 minutes)</p></main></body></html>
